export const alexanderstreetEditions = [{"source_id":"alexanderstreet:3834388","title":"A Community of Character: Toward a Constructive Christian Social Ethic","authors":["Stanley Hauerwas"],"publisher":"University of Notre Dame Press","platform":"alexanderstreet","isbns":["9780268007355"],"subtitle":"","description":"Recognized as a leading theological ethicist, Stanley Hauerwas applies his theory of the narrative formation of Christian character to the field of social ethics. He advances his ideas by showing why any consideration cannot be divorced from the kind of community the church is and should be. He also challenges the dominant assumption of contemporary Christian social ethics that there is a special relation between Christianity and some form of liberal democratic social system.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1868308","title":"Against the Wind: Memoir of a Radical Christian","authors":["Dorothee Sölle"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800630799"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]},{"family":"Littérature et études littéraires","subcategory":"Biographie","details":[]}]},{"source_id":"alexanderstreet:3834475","title":"Being With God: Trinity, Apophaticism, and Divine-Human Communion","authors":["Aristotle Papanikolaou, fl. 2006"],"publisher":"University of Notre Dame Press","platform":"alexanderstreet","isbns":["9780268038311"],"subtitle":"","description":"'Being With God is an exceedingly important and well-written book on Orthodox theology of the Trinity. It not only explains the work of two major contemporary Orthodox theologians; it also lends vital insight into the nature and character of contemporary Orthodox theology in general.' -- Vigen Guroian, Loyola College in Maryland. 'This is a splendid work of hard-won insights into crucial figures in the development of contemporary theology. Aristotle Papanikolaou makes an original contribution that will be of great interest not only to students in the area of Eastern Orthodox theology but to anyone studying Christian anthropology, metaphysics, Trinitarian thought, or comparative theological method.' -- Mark McIntosh, Department of Theology, Loyola University of Chicago. The central task of Being With God is an analysis of the relation between apophaticism, Trinitarian theology, and divine-human communion through a critical comparison of the Trinitarian theologies of the Eastern Orthodox theologians Vladimir Lossky (1903–58) and John Zizioulas (1931– ), arguably two of the most influential Orthodox theologians of the past century. These two theologians identify as the heart and center of all theological discourse the realism of divine-human communion, which is often understood in terms of the familiar Orthodox concept of theosis, or divinization. The Incarnation, according to Lossky and Zizioulas, is the event of a real divine-human communion that is made accessible to all; God has become human so that all may participate fully in the divine life. Aristotle Papanikolaou shows how an ontology of divine-human communion is at the center of both Lossky’s and Zizioulas's theological projects. He also shows how, for both theologians, this core belief is used as a self-identifying marker against 'Western' theologies. Papanikolaou maintains, however, that Lossky and Zizioulas hold profoundly different views on how to conceptualize God as the Trinity. Their key difference is over the use of apophaticism in theology in general and especially the relation of apophaticism to the doctrine of the Trinity. For Lossky, apophaticism is the central precondition for a Trinitarian theology; for Zizioulas, apophaticism has a much more restricted role in theological discourse, and the God experienced in the Eucharist is not the God beyond being but the immanent life of the Trinitarian God. Papanikolaou provides readers with a richer understanding of contemporary Orthodox theology through his analysis of the consensus and debate between two leading Orthodox theologians.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3360808","title":"Belief in Science and in Christian Life","authors":["Peter Forster, 1950-, Colin E. Gunton, 1941-2003, Daniel W. Hardy, 1930-2007, John Barr, fl. 1998, John C. Puddefoot, fl. 1998, Thomas Forsyth Torrance, 1913-2007 and Arthur Walter James"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9781579101312"],"subtitle":"","description":"This book, edited by Thomas F. Torrance, is the result of a conference of theologians and scientists who met to discuss the influence of philosopher-scientist Michael Polyani on Christian convictions in the context of the scientific revolution.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3567113","title":"Changing Horizons: Explorations in Feminist Interpretation","authors":["Elisabeth Schüssler Fiorenza"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800698072"],"subtitle":"","description":"Changing Horizons is the second of two volumes highlighting the ways in which Elisabeth Schussler Fiorenza's work constructs a critical feminist theory and praxis of liberation, in relation to the biblical text and its legacy, and in relation to the theological and ecclesial setting of today. In these essays collected from her extraordinary career, Schussler Fiorenza attempts to free both biblical studies and theology from disciplinary constraints and assumptions that have allowed them to acquiesce and even perpetuate forms of oppression—from racism and poverty to colonialism and gender equality. While Schussler Fiorenza's feminist critical approach begins with the experience of women, that experience is appropriated through the lens of critical theory and a critical understanding of social and religious oppressions. It is, further, political in its aim to dethrone kyriarchal structures and foment genuinely egalitarian community in church and society.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie","Textes sacrés et exégèse"]}]},{"source_id":"alexanderstreet:3925047","title":"Christ and Evolution: A Study of the Doctrine of Redemption in the Light of Modern Knowledge","authors":["George A. Barton"],"publisher":"University of Pennsylvania Press","platform":"alexanderstreet","isbns":["9781512810103"],"subtitle":"","description":"Christianity viewed against the theory of evolution, the new physics, behavioristic psychology, to prove the Christ is still the best guide for the advancement of the world.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2295180","title":"Christ the Liberator","authors":["Jon Sobrino"],"publisher":"Orbis Books","platform":"alexanderstreet","isbns":["9781570753725"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3567299","title":"Christian Doctrine and the Grammar of Difference","authors":["Janice McRandal"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9781451484472"],"subtitle":"","description":"Christian Doctrine and the Grammar of Difference argues that the most potent and resourceful theological response to the challenging questions of gender and difference is to be found in a retrieval of a doctrinal framework for feminist theology. In particular, it is suggested that a doctrinal narrative of creation, fall, and redemption --underpinned by the doctrinal grammar of the Trinity -- provides resources to resolve the theological impasse of difference in contemporary feminist theology. The divine economy reveals a God who enters into history and destabilizes fixed binaries and oppressive categories. The biblical narrative discloses a subtle yet potent fluidity to the Triune relationships. As created subjects -- precisely in our difference -- we are sustained, affirmed, and drawn back into the Triune life. The subtleties of divine transgression are already recognized in the patterns of the liturgy, in prayer, and in practices of contemplation. Here, bodies not only encounter the transgressive love of God but are enabled to inhabit their differentiated humanity with distinctiveness and grace. The grammar of Christian faith cannot ultimately be uncovered except in prayer, opened beyond itself to a source of life and giving.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3908729","title":"Christian Ethics and Contemporary Moral Problems","authors":["Michael Banner"],"publisher":"Cambridge University Press","platform":"alexanderstreet","isbns":["9780521625548"],"subtitle":"","description":"Michael Banner explores the significance of Christian belief for several ethical issues including euthanasia, the environment, abortion, the family, and sexual ethics. He shows the crucial difference which Christian belief makes to an understanding of these issues,  and demonstrates some of the weaknesses of certain popular approaches to them.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3358564","title":"Christian Existence Today","authors":["Stanley Hauerwas"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9781608997107"],"subtitle":"","description":"Stanley Hauerwas begins this volume with a vigorous response to the charge of sectarianism leveled against his work by James Gustafson, among others. 'Show me where I am wrong about God, Jesus, the limits of liberalism, the nature of the virtues, or the doctrine of the church,' Hauerwas replies to his critics, 'but do not shortcut that task by calling me a sectarian.' The essays that follow explore in a lucid, compelling, firm, and provocative way the church's nature, message, and ministry in the world. Hauerwas writes on the church as God's new language, on clerical character, on the pastor as prophet, on the ministry of the local congregation, on grace and public virtue, and on the relation of church and university. Underlying Hauerwas's argument is his conviction that 'the most important knowledge Christian convictions involve, and there is much worth knowing for which Christians have no special claim, requires a transformation of the self. Christianity is no 'world view,' not a form of primitive metaphysics, that can be assessed in comparison to alternative 'world views.' Rather, Christians are people who remain convinced that the truthfulness of their beliefs must be demonstrated in their lives. There is a sense in which Christian convictions are self-referential, but the reference is not to propositions but to lives.'","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3362794","title":"Christian Wisdom: Desiring God and Learning in Love","authors":["David F. Ford"],"publisher":"Cambridge University Press","platform":"alexanderstreet","isbns":["9780521875455"],"subtitle":"","description":"What is Christian wisdom for living in the twenty-first century? Where is it to be found? How can it be learnt? In the midst of diverse religions and worldviews and the demands and complexities of our world, David Ford explores a Christian way of uniting love of wisdom with wisdom in love. Core elements are the 'discernment of cries', the love of God for God's sake, interpretation of scripture, and the shaping of desire in faith. Case studies deal with inter-faith wisdom among Jews, Christians and Muslims, universities as centers of wisdom as well as knowledge and know-how and the challenge of learning disabilities. Throughout, there is an attempt to do justice to the pre-modern, modern and postmodern while grappling with scripture, tradition and the cries of the world today. Ford opens up the rich resources of Christianity in engaging with the issues and urgencies of contemporary life.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Spiritualité"]}]},{"source_id":"alexanderstreet:1868482","title":"Church in the Power of the Spirit: A Contribution to Messianic Ecclesiology","authors":["Jürgen Moltmann"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800628215"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1880089","title":"Church, Ecumenism and Politics: New Endeavors in Ecclesiology","authors":["Benedict XVI, Pope"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9781586172176"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3360827","title":"Credo: The Apostles' Creed Explained for Today","authors":["Hans Küng"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9781592443451"],"subtitle":"","description":"In this small, lucid gem of a book, the controversial Swiss theologian Hans Kung offers his thoughtful explanation of what the ancient profession of Christian faith can mean for us today. In doing so, Kung also flings a challenging response to the new Catechism of the Catholic Church, for 'Credo' is a fresh answer to the conservative stance of today's Vatican -- a salvo that cannot be ignored. While controversy inevitably surrounds all of Kung's books, 'Credo' is his most accessible and straightforward work to date, written simply for all readers. It is the summation of a lifetime of theological thought by one of Christianity's most profound and original thinkers -- a book that reaches out to non-Catholic Christians, as well as to Jews, Moslems, and those of the Eastern religions, and that gives everyone the dignity he or she deserves. Kung asks the big questions: Can we still believe in God? In the Virgin birth? In the divinity of Jesus? In his resurrection? In eternal life? And Kung also asks many unusual questions: Did Auschwitz disprove the existence in God? Is there any real difference between Jesus and the Buddha? Is resurrection from the dead un-Jewish? Must the Church be undemocratic? The answers he gives are, as always, profound and unexpected. This is not a book just for Catholics or even just for Christians, but a book for anyone with an interest in how religion can be integrated into contemporary life. Here is a great modern intellect -- at his most reader-friendly.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1880386","title":"Does Jesus Know Us? Do We Know Him?","authors":["Hans Urs von Balthasar"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9780898700237"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1880422","title":"Dogma and Preaching","authors":["Benedict XVI, Pope"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9781586173272"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3930167","title":"Ecumenism: Present Realities and Future Prospects","authors":["Stephen Sykes, 1939-2014, Hermann J. Pottmeyer, 1934-, Jean M. R. Tillard, 1927-, Thomas Hopko, 1939-2015, Michael A. Signer, 1945-2009, Peter G. Coleman, fl. 1997, Anna-Marie Aagaard, 1935-, Edward Idris Cassidy, 1924-, Frans Bouwen, fl. 1997, Jaroslav Pelikan, 1923-2006, Lawrence S. Cunningham, fl. 1998 and Edward A. Malloy"],"publisher":"University of Notre Dame Press","platform":"alexanderstreet","isbns":["9780268027520"],"subtitle":"","description":"This is an important collection of the historical work presented at the Tantur Ecumenical Center conference in Jerusalem held in the spring of 1997. The Tantur conference commemorates the twenty-fifth anniversary of the center's founding with a gathering of internationally known ecumenists who represent many decades of serious engagement with Christian dialogue. Their resulting work is an inimitable assessment of the current state of ecumenical relations more than three decades after the Second Vatican Council. Ecumenism 'takes the pulse' of ecumenical relationships by making realistic judgments about future prospects for greater Christian unity. This volume is a pledge for the future of religious unity and a valuable resource for all those interested in the state of ecumenism in Christianity today.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Histoire et étude des religions"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Histoire et étude des religions","Christianisme"]}]},{"source_id":"alexanderstreet:3360836","title":"Faith and Fratricide","authors":["Gregory Baum, 1923- and Rosemary Radford Ruether"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9780965351751"],"subtitle":"","description":"Since the Nazi holocaust took the lives of a third of the Jewish people of the world, the Christian Church has been engaged in a self-examination of its own historical role in the creation of antisemitism. In this major contribution to that search, theologian Rosemary Radford Ruether explores the roots of antisemitism from new perspectives.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Spiritualité"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Judaïsme","Histoire et étude des religions"]}]},{"source_id":"alexanderstreet:3362812","title":"Fields of Faith: Theology and Religious Studies for the Twenty-First Century","authors":["Ben Quash, 1968-, Oliver Davies, 1956-, Maleiha Malik, fl. 2005, Janet Martin Soskice, 1951-, John W. De Gruchy, 1939-, Nicholas Adams, fl. 2005, Eamon Duffy, 1947-, Peter Ochs, 1950-, Julius J. Lipner, 1946-, Rowan Williams, 1950-, Gavin Dennis Flood, 1954-, Sarah Anne Coakley, 1951-, Denys Turner, 1942-, Michael J. Buckley, 1931- and David F. Ford"],"publisher":"Cambridge University Press","platform":"alexanderstreet","isbns":["9780521847377"],"subtitle":"","description":"This book was first published in 2005. How will the study of theology and the religions in higher education be shaped in the coming century? This book offers several different perspectives on this field of study with suggestions for a future in which theology and religious studies are pursued together. There are examples of the interplay of theology and religious studies with reference to a range of topics: God, love, scripture, worship, argument, reconciliation, friendship and justice. The contributors practise different disciplines within the field, often in combination, covering theology, philosophy, history, phenomenology, literary studies, hermeneutics, politics, ethics and law. Their specialisms embrace Judaism, Christianity, Islam and Indian religions, with particular focus on the field in Europe, the US and South Africa. Recognizing the significance of the religions and of higher education, the book explores what best practice can be adopted to fulfil responsibilities towards academic disciplines, the religions and the societies of which they are part.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie","Spiritualité"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie","Histoire et étude des religions"]}]},{"source_id":"alexanderstreet:2130999","title":"Gemeinsames Leben. Das Gebetbuch der Bibel (Psalmen)","authors":["Dietrich Bonhoeffer"],"publisher":"Gütersloher Verlagshause","platform":"alexanderstreet","isbns":["9783579018751"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Textes sacrés et exégèse","Spiritualité"]}]},{"source_id":"alexanderstreet:2290757","title":"Hannah's Child: A Theologian's Memoir","authors":["Stanley Hauerwas"],"publisher":"William B. Eerdmans Publishing Company","platform":"alexanderstreet","isbns":["9780802864871"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]}],"paths":[{"family":"Littérature et études littéraires","subcategory":"Biographie","details":[]}]},{"source_id":"alexanderstreet:1867792","title":"Holy Trinity, Perfect Community","authors":["Leonardo Boff"],"publisher":"Orbis Books","platform":"alexanderstreet","isbns":["9781570753329"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3924482","title":"Holy War, Martyrdom, and Terror: Christianity, Violence, and the West","authors":["Philippe Buc"],"publisher":"University of Pennsylvania Press","platform":"alexanderstreet","isbns":["9780812246858"],"subtitle":"","description":"Holy War, Martyrdom, and Terror examines the ways that Christian theology has shaped centuries of conflict from the Jewish-Roman War of late antiquity through the First Crusade, the French Revolution, and up to the Iraq War. By isolating one factor among the many forces that converge in war -- the essential tenets of Christian theology --Philippe Buc locates continuities in major episodes of violence perpetrated over the course of two millennia. Even in secularized or explicitly non-Christian societies, such as the Soviet Union of the Stalinist purges, social and political projects are tied to religious violence, and religious conceptual structures have influenced the ways violence is imagined, inhibited, perceived, and perpetrated. The patterns that emerge from this sweeping history upend commonplace assumptions about historical violence, while contextualizing and explaining some of its peculiarities. Buc addresses the culturally sanctioned logic that might lead a sane person to kill or die on principle, traces the circuitous reasoning that permits contradictory political actions, such as coercing freedom or pardoning war atrocities, and locates religious faith at the backbone of nationalist conflict. He reflects on the contemporary American ideology of war -- one that wages violence in the name of abstract notions such as liberty and world peace and that he reveals to be deeply rooted in biblical notions. A work of extraordinary breadth, Holy War, Martyrdom, and Terror connects the ancient past to the troubled present, showing how religious ideals of sacrifice and purification made violence meaningful throughout history.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Histoire et étude des religions"]}]},{"source_id":"alexanderstreet:3834418","title":"In Good Company: The Church as Polis","authors":["Stanley Hauerwas"],"publisher":"University of Notre Dame Press","platform":"alexanderstreet","isbns":["9780268011796"],"subtitle":"","description":"By exposing a different account of politics -- the church as polis and 'counterstory' to the world's politics -- Stanley Hauerwas helps Christians to recognize the unifying beliefs and practices that make them a political entity apart from the rest of the world.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1880851","title":"Introduction to Christianity, 2nd edition","authors":["Benedict XVI, Pope"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9781586170295"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3567101","title":"Issues in Contemporary Christian Thought","authors":["Duane Olson, fl. 2011"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800696658"],"subtitle":"","description":"Duane Olson's new textbook uniquely focuses on the central points at issue in contemporary Christian reflection. Olson's clear and concise overview roots contemporary questions firmly in Christian responses to the Enlightenment. This allows Olson to unfold those questions as bequeathed by modernity and to show how the radical reframing of the current period actually builds on the diversity of those lingering concerns. Olson discusses the range of contemporary opinions, their rationales, and what's at stake. He illustrates these alternate frameworks as they play out in central concerns over the being of God in relation to the universe, how to understand the figure of Christ today, and the distinctively new notions of being human. Olson's text includes reflection and research questions, suggestions for further reading, and a glossary.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1865078","title":"Jesus and Creativity","authors":["Gordon D. Kaufman"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800696344"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1865100","title":"Jesus Christ for Today's World","authors":["Jürgen Moltmann"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800628178"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1867874","title":"Jesus Christ Liberator","authors":["Leonardo Boff"],"publisher":"Orbis Books","platform":"alexanderstreet","isbns":["9780883442364"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2295755","title":"Jesus Christ: Savior & Lord","authors":["Donald G. Bloesch"],"publisher":"InterVarsity Press","platform":"alexanderstreet","isbns":["9780830827541"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2294185","title":"Jesus in Latin America","authors":["Jon Sobrino"],"publisher":"Orbis Books","platform":"alexanderstreet","isbns":["9780883444122"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3567367","title":"Jesus' Abba: the God Who Has Not Failed","authors":["John B. Cobb, Jr."],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9781506405704"],"subtitle":"","description":"The church has emphasized ideas about God that have marginalized Jesus' understanding of his spiritual Father, his Abba. We commonly think of God as a demanding lawgiver and judge, an omnipotent ruler, or an ultimate philosophical principle. None of these works well today.  In contrast, Jesus' view of God as spiritual Abba still truly works when it is given a chance. Christians should be open to accepting the ideas of the one they call Lord and Savior. In Jesus' Abba, one of the greatest theologians of this generation boldly argues for a new view of God, through the eyes of Jesus. John B. Cobb Jr. interprets the whole of Jesus' life and ministry, and death and resurrection, in light of Jesus' understanding of God. He also shows that Paul shared this understanding and that it played a central role in Paul's churches. Ultimately, Cobb argues that Jesus' view of God fits our actual experience today, that it is supported by the evidence of the sciences, and that it encourages appreciative learning from other wisdom traditions and cooperation with them in redeeming the world. With this book, John B. Cobb Jr. makes his ultimate and most impassioned plea for us to rediscover God through Jesus.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3360879","title":"Kingdom and the Church","authors":["Thomas Forsyth Torrance"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9781579100124"],"subtitle":"","description":"In this book, the problem of the reality of salvation is addressed by T.F. Torrance's doctrine of 'the vicarious humanity of Christ.' Through this approach, salvation as humanization is affirmed, yet without the problems of anthropocentric theologies. This book is unique in that it offers both a survey of contemporary Christian thinking on salvation as well as a constructive alternative based on Torrance's doctrine, a significant yet neglected contribution to modern theology.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1880971","title":"Mary for Today","authors":["Hans Urs von Balthasar"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9780898701906"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2293989","title":"Mary Mother of God, Mother of the Poor","authors":["Maria Clara Lucchetti Bingemer, 1949- and Ivone Gebara"],"publisher":"Orbis Books","platform":"alexanderstreet","isbns":["9780883446386"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1881003","title":"Mary: The Church at the Source","authors":["Hans Urs von Balthasar, 1905-1988 and Benedict XVI, Pope"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9781586170189"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3996526","title":"Modernism and the Christian Faith","authors":["John Alfred Faulkner"],"publisher":"Routledge (Publisher)","platform":"alexanderstreet","isbns":["9781138812826"],"subtitle":"","description":"First published in 1921, this title addresses the difficulties faced by the modern Christian Church in terms of polity, administration, and the development of liberal theology, in light of the changes taking place within society at the start of the twentieth century. John Alfred Faulkner deals with such subjects as the nature of authority within Christian theology and its relationship to liberalism, Christianity and the supernatural, and the shift in emphasis from the metaphysical Christ to the moral or practical Christ and his historical reality. An interesting reissue, this title will be of particular value to theology students researching the role of Christianity in modern society, and the impact of liberal theology on its core doctrines.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Spiritualité"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1865210","title":"On Human Being: Christian Anthropology in Conflicts of Present","authors":["Jürgen Moltmann"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800610661"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2409926","title":"Ontological and Psychological Constitution of Christ","authors":["Bernard Lonergan"],"publisher":"University of Toronto Press","platform":"alexanderstreet","isbns":["9780802084743"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2294303","title":"Philosophical and Theological Papers, 1958-1964","authors":["Bernard Lonergan"],"publisher":"University of Toronto Press","platform":"alexanderstreet","isbns":["9780802034748"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"alexanderstreet:2745377","title":"Philosophical and Theological Papers, 1965-1980","authors":["Bernard Lonergan"],"publisher":"University of Toronto Press","platform":"alexanderstreet","isbns":["9780802086389"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"alexanderstreet:1905825","title":"Presence and Thought: An Essay on the Religious Philosophy of Gregory of Nyssa","authors":["Hans Urs von Balthasar"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9780898705218"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Théologie"]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"alexanderstreet:1905919","title":"Principles of Christian Morality","authors":["Heinz Schürmann, 1913-1999, Benedict XVI, Pope, 1927- and Hans Urs von Balthasar"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9780898700862"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1866443","title":"Protestantism and Progress: The Significance of Protestantism for the Rise of the Modern World","authors":["Ernst Troeltsch"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800632007"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Histoire et étude des religions"]}]},{"source_id":"alexanderstreet:3820056","title":"Reading the Gospel","authors":["John S. Dunne"],"publisher":"University of Notre Dame Press","platform":"alexanderstreet","isbns":["9780268016685"],"subtitle":"","description":"Using the method of spiritual reading, lectio divina or 'divine reading' as it is called in monasteries, John S. Dunne sets out his interpretation of the evangelists, especially John, in Reading the Gospel. Reading the Gospels, according to Dunne, means passing over into the relation of Jesus with his God, the God he calls Abba in prayer, and then coming back from that with a changed vision of life and death. If I pass over into the relation of Jesus with God, then Jesus disappears from in front of me and I find myself in relation to what Jesus calls 'my God and your God.' When I come back to myself, I see my life in terms of his life and my death in terms of his death and resurrection, and I am able to say with Paul, 'I live now, not I, but Christ lives in me.'","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Textes sacrés et exégèse"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Textes sacrés et exégèse","Spiritualité"]}]},{"source_id":"alexanderstreet:4684108","title":"Reconstructing Christian Ethics: Selected Writings","authors":["Frederick Denison Maurice"],"publisher":"Westminster John Knox Press","platform":"alexanderstreet","isbns":["9780664256012"],"subtitle":"","description":"As one of the major British theologians and ethicists of the nineteenth century, F. D. Maurice is considered a forerunner of the contemporary ecumenical movement. His writings and work were an articulation of his theology, which emphasized the inclusiveness of Christianity despite ideological divisions within the Christian community. Maurice proposed a primary unifying principle, based on the dynamic love of God for humankind in all its diversity, that would bring the various Christian traditions into a catholic whole. This volume brings to readers a selection of Maurice's moral writings based on his theological worldview. It is the only anthology of his ethical writings currently available. The Library of Theological Ethics series focuses on what it means to think theologically and ethically. It presents a selection of important and otherwise unavailable texts in easily accessible form. Volumes in this series will enable sustained dialogue with predecessors though reflection on classic works in the field.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3353181","title":"The Apostles Creed in Light of Today's Questions","authors":["Wolfhart Pannenberg"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9781579104405"],"subtitle":"","description":"This book, by Wolfhart Pannenberg, is an exploration of the historical interpretation of the Apostles Creed in order to demonstrate the relevance of its articles for the present day.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3567150","title":"The Bonhoeffer Reader","authors":["Dietrich Bonhoeffer"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800699451"],"subtitle":"","description":"For the first time the essential theological writings of Dietrich Bonhoeffer have been drawn together in a helpful one-volume format. The Bonhoeffer Reader brings the best English translation to students, and provides a ready-made introduction to the thought of this essential thinker.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2291250","title":"The Burning Bush: On the Orthodox Veneration of the Mother of God","authors":["Sergei Bulgakov"],"publisher":"William B. Eerdmans Publishing Company","platform":"alexanderstreet","isbns":["9780802845740"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1906032","title":"The Christian Faith: An Essay on the Structure of the Apostles' Creed","authors":["Henri de Lubac"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9780898700534"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Spiritualité"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3358524","title":"The Christian Frame of Mind","authors":["W. Jim Neidhardt, 1934- and Thomas Forsyth Torrance"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9781498225878"],"subtitle":"","description":"The Christian Frame of Mind: Reason, Order, and Openness in Theology and Natural Science is an exhilarating exploration by one of this century's premier theologians of the relationship between science and theology. This collection of essays, which focuses on themes central to Thomas F. Torrance's lifelong work of integrating Judaeo-Christian theology and natural science, illuminates the distinctive contribution of the Christian frame of mind to human life and thought particularly in the rise of modern science. Arguing to close the gap between theological and natural science erroneously opened by 'the narrow-minded rationalism of the Enlightenment,' Dr. Torrance builds upon the work of scientists such as James Clerk Maxwell, Albert Einstein, and Michael Polanyi in promoting dialogue between the two disciplines. The resultant conversation is a brilliant and stirring analysis of common ground in scientific and theological inquiry. Torrance discards a dualist separation for a unitary understanding of reality, in which the invisible guides the interpretation of the visible as scientist and theologian alike adopt self critical openness and the auditive mode of inquiry in response to the pressing questions of their task. Dr. Torrance urges this unitary understanding of the intelligibility of the universe as a shared goal of science and theology. His vision of a foundational convergence between them, where the 'boundary points' of contingent reality find their reference in the transcendent, uncreated reality of the Word of God is breathtaking in beauty and scope. The introduction by Dr. W. Jim Neidhardt, physics professor at the New Jersey Institute of Technology, provides a lucid summary of key themes in Torrance's lifelong integrative work.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3820045","title":"The Church of the Holy Spirit","authors":["Rowan Williams, 1950- and Nicholas Afanasiev"],"publisher":"University of Notre Dame Press","platform":"alexanderstreet","isbns":["9780268020422"],"subtitle":"","description":"The Church of the Holy Spirit, written by Russian priest and scholar Nicholas Afanasiev (1893–1966), is one of the most important works of twentieth-century Orthodox theology. Afanasiev was a member of the 'Paris School' of emigre intellectuals who gathered in Paris after the Russian revolution, where he became a member of the faculty of St. Sergius Orthodox Seminary. The Church of the Holy Spirit, which offers a rediscovery of the Eucharistic and communal nature of the church in the first several centuries, was written over a number of years beginning in the 1940s and continuously revised until its posthumous publication in French in 1971. Vitaly Permiakov's lucid translation and Michael Plekon's careful editing and substantive introduction make this important work available for the first time to an English-speaking audience.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2295839","title":"The Church: Sacraments, Worship, Ministry, Mission","authors":["Donald G. Bloesch"],"publisher":"InterVarsity Press","platform":"alexanderstreet","isbns":["9780830814169"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3353197","title":"The Doctrine of Jesus Christ: The Auburn Lectures","authors":["Thomas Forsyth Torrance"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9781579107284"],"subtitle":"","description":"This book, by Thomas F. Torrance, is a collection of lectures presented in 1938-1939 at Auburn Theological Seminary in New York City.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1906105","title":"The Drama of Atheist Humanism","authors":["Henri de Lubac"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9780898704433"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Histoire et étude des religions"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Histoire et étude des religions"]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"alexanderstreet:4683530","title":"The Holy Grail and the Eucharist","authors":["Sergei Bulgakov"],"publisher":"SteinberBooks","platform":"alexanderstreet","isbns":["9780940262812"],"subtitle":"","description":"These two moving studies by the eminent Orthodox theologian and sophiologist Father Sergei Bulgakov are remarkable in many ways. The first is a unique consideration—from the point of view of Eastern Christianity—of the Holy Grail, the chalice used by Joseph of Arimathea to catch the blood and water as it flowed from Jesus' side when it was pierced on the Cross by the spear of Longinus. This moment is described in John 19:34. Bulgakov's essay is a 'dogmatic exegesis' of this passage in which, with astounding passion and precision, he reveals that the Earth itself and hence the human universe is the Grail wherein Christ lives forever. The second essay is also unique—the most important contribution to eucharistic theology by an Orthodox theologian. In the West, the meaning of the Communion bread and wine as the Christ's Body and Blood has been interpreted largely in philosophical terms deriving from Aristotle and Thomas Aquinas. Bulgakov insists on a Christological, Gospel-based interpretation, one with tremendous significance for our understanding of the supernatural and Sophianic nature of a world interpenetrated by the divine. This little book is a priceless gift, enriching our understanding of the Christian mystery and two of its deepest aspects, the Grail and the Eucharist. This book is part of the Esalen–Lindisfarne Library of Russian Philosophy.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie","Textes sacrés et exégèse"]}]},{"source_id":"alexanderstreet:1906683","title":"The Office of Peter and the Structure of the Church, 2nd Edition","authors":["Hans Urs von Balthasar"],"publisher":"Ignatius Press","platform":"alexanderstreet","isbns":["9781586172282"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2292107","title":"The Politics of Jesus: Vicit Agnus Noster","authors":["John Howard Yoder"],"publisher":"William B. Eerdmans Publishing Company","platform":"alexanderstreet","isbns":["9780802807342"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1866593","title":"The Responsibility of the Church for Society and Other Essays","authors":["Helmut Richard Niebuhr"],"publisher":"Westminster John Knox Press","platform":"alexanderstreet","isbns":["9780664230487"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2293886","title":"The True Church and the Poor","authors":["Jon Sobrino"],"publisher":"Orbis Books","platform":"alexanderstreet","isbns":["9780883445136"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:2292620","title":"Trinity and Society","authors":["Leonardo Boff"],"publisher":"Orbis Books","platform":"alexanderstreet","isbns":["9780883446232"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1870196","title":"Trinity and the Kingdom","authors":["Jürgen Moltmann"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800628253"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:4683546","title":"War, Progress, and the End of History: Three Conversations, Including a Short Story of the Anti-Christ","authors":["Vladimir Solovyov"],"publisher":"SteinberBooks","platform":"alexanderstreet","isbns":["9780940262355"],"subtitle":"","description":"In this prophetic, millennial work, written by Russia's greatest philosopher at the end of the last century, the great task facing humanity as progress races to end history is the resistance to evil. Solovyov addresses what seem to him the three main trends of our time: economic materialism, Tolstoyan abstract moralism, and Nietzschean hubris--the first is already present, the second imminent, while the last is the apocalyptic precursor of the Antichrist.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]},{"family":"Sciences humaines et sociales","subcategory":"Philosophie","details":[]}]},{"source_id":"alexanderstreet:4684112","title":"What Christians Really Believe & Why","authors":["Stanley J. Grenz"],"publisher":"Westminster John Knox Press","platform":"alexanderstreet","isbns":["9780664257323"],"subtitle":"","description":"People today are searching for something to believe in. How can they choose between conflicting belief systems and find answers to their questions? In this book, Stanley Grenz presents the central tenets of Christian faith clearly and concisely, answering the most common questions and helping readers strengthen their understanding of Christianity.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:1870508","title":"Who is Christ for Us?","authors":["Dietrich Bonhoeffer"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800634803"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Théologie"]}]},{"source_id":"alexanderstreet:3360778","title":"Women of Spirit: Female Leadership in the Jewish and Christian Traditions","authors":["Ellen M. Umansky, fl. 1998, Christa Ressmeyer Klein, fl. 1998, Virginia Lieson Brereton, fl. 1998, Dorothy C. Bass, 1949-, Mary Ewens, fl. 1998, Donald W. Dayton, fl. 1998, Lucille Sider Dayton, 1946-, Nancy Hardesty, 1941-2011, Barbara Brown Zikmund, fl. 1998, Catherine F. Smith, fl. 1998, Elaine C. Huber, fl. 1998, Ruth P. Liebowitz, fl. 1998, Elisabeth Schüssler Fiorenza, 1939-, Eleanor Commo McLaughlin, fl. 1998, Rosemary Radford Ruether, 1936- and Norene Carter, fl. 1998"],"publisher":"Wipf & Stock","platform":"alexanderstreet","isbns":["9781579101091"],"subtitle":"","description":"A compilation of essays on the role of women in the institutional and ordained leadership of Western religion. The authors discuss religious women as charismatic leaders, holy women, martyrs, dissenters, renewers and reformers, as well as theological images of the feminine -- in God, the Christ-Church relationship, and the self. The studies are historical and descriptive both, from the early church to the present day.","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Judaïsme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Judaïsme","Histoire et étude des religions"]}]},{"source_id":"alexanderstreet:1864383","title":"Young Bonhoeffer 1918-1927","authors":["Dietrich Bonhoeffer"],"publisher":"Fortress Press","platform":"alexanderstreet","isbns":["9780800683092"],"subtitle":"","description":"","from":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme"]}],"paths":[{"family":"Sciences humaines et sociales","subcategory":"Religion","details":["Christianisme","Histoire et étude des religions"]}]}];
